insert into tax.prepayment_templates
  (country, valid_from, valid_to, valid_on, method, month_basis, instalments, surcharge_percent, exempt_up_to, legal_reference, source_key)
values
  ('ES', date '2025-01-01', null, 'period_start'::tax.validity_basis, 'share_of_reference_tax', 'calendar', '[{"day":20,"month":4,"sequence":1,"share_percent":18},{"day":20,"month":10,"sequence":2,"share_percent":18},{"day":20,"month":12,"sequence":3,"share_percent":18}]'::jsonb, null, null, 'Ley 27/2014, art. 40.1 y 40.2 — pago fraccionado en los primeros 20 días naturales de abril, octubre y diciembre, a cuenta del período impositivo en curso el día 1 de cada uno de esos meses; su base es la cuota íntegra del último período cuyo plazo de declaración estuviese vencido, minorada en las deducciones y bonificaciones y en las retenciones e ingresos a cuenta de aquel, y la cuantía es el 18 por ciento de esa base; no lo efectúan las entidades del art. 29, apartados 4 y 5. La modalidad del art. 40.3 y el art. 40.4 (porcentajes modificables por la Ley de Presupuestos) no se calculan', 'lis')
on conflict (country, valid_from) do update set
  valid_to          = excluded.valid_to,
  valid_on          = excluded.valid_on,
  method            = excluded.method,
  month_basis       = excluded.month_basis,
  instalments       = excluded.instalments,
  surcharge_percent = excluded.surcharge_percent,
  exempt_up_to      = excluded.exempt_up_to,
  legal_reference   = excluded.legal_reference,
  source_key        = excluded.source_key;
